        "lead": "VICR는 한 달 새 약 70% 올랐고, 이는 생산 증설 기대의 결과다. 공장이 가동 한계에 가까워 증설 발표가 임박했다는 분석이 나왔다. 증설이 확정되지 않으면 이 이야기는 약해진다.",
