        "ticker": "ATEX",
        "company": "미국 전력·가스·수도 회사에 쓰이는 900MHz 주파수 면허를 보유하고, 이를 임대·매각해 돈을 버는 통신 회사. 매출 규모는 아주 작고 주파수 거래 성사 여부에 실적이 크게 흔들린다.",
        "lead": "6개월 상승률은 129.8%로 크지만 최근 3개월은 21.4% 하락해 최근 상승세는 꺾인 상태다. 상승 논리는 희소한 900MHz 주파수가 전력회사 계약과 위성 활용으로 이어질 수 있다는 기대다. 분기 매출이 아직 200만 달러 안팎이라, 실제 계약 소식이 나오지 않으면 이 이야기는 힘을 잃는다.",
